import{_ as t,o,c as d,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"11 — Từ Điển Thực Thể Dữ Liệu & Kiến Trúc Lưu Trữ Đa Cơ Sở Dữ Liệu (Data Entities & Glossary)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/11-data-entities-glossary.md","filePath":"ba/11-data-entities-glossary.md"}'),n={name:"ba/11-data-entities-glossary.md"};function a(i,e,s,l,r,g){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="_11-—-tu-đien-thuc-the-du-lieu-kien-truc-luu-tru-đa-co-so-du-lieu-data-entities-glossary" tabindex="-1">11 — Từ Điển Thực Thể Dữ Liệu &amp; Kiến Trúc Lưu Trữ Đa Cơ Sở Dữ Liệu (Data Entities &amp; Glossary) <a class="header-anchor" href="#_11-—-tu-đien-thuc-the-du-lieu-kien-truc-luu-tru-đa-co-so-du-lieu-data-entities-glossary" aria-label="Permalink to &quot;11 — Từ Điển Thực Thể Dữ Liệu &amp; Kiến Trúc Lưu Trữ Đa Cơ Sở Dữ Liệu (Data Entities &amp; Glossary)&quot;">​</a></h1><p>&gt; [&lt;&lt; 10 - Roles &amp; Permissions Matrix](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/10-roles-permissions-matrix.md) | [Overview](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/00-overview.md) | [Tiếp: 12 - State Machines &gt;&gt;](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/12-state-machines.md) &gt; &gt; Tài liệu này tổng hợp toàn bộ các thực thể nghiệp vụ (Domain Entities) của hệ thống <strong>BrandHub</strong>, phân bổ trên 4 hệ quản trị cơ sở dữ liệu (<strong>PostgreSQL</strong>, <strong>MongoDB</strong>, <strong>Neo4j</strong>, <strong>Redis</strong>) và đối chiếu trực tiếp với <strong>141 Yêu cầu Chức năng (<code>3.2.1</code> – <code>3.10.14</code>)</strong>.</p><hr><h2 id="_1-kien-truc-phan-tang-luu-tru-đa-co-so-du-lieu-polyglot-persistence" tabindex="-1">1. Kiến trúc Phân tầng Lưu trữ Đa Cơ sở Dữ liệu (Polyglot Persistence) <a class="header-anchor" href="#_1-kien-truc-phan-tang-luu-tru-đa-co-so-du-lieu-polyglot-persistence" aria-label="Permalink to &quot;1. Kiến trúc Phân tầng Lưu trữ Đa Cơ sở Dữ liệu (Polyglot Persistence)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Hệ quản trị CSDL</th><th style="text-align:left;">Vai trò trong Kiến trúc</th><th style="text-align:left;">Các Thực thể Chính được Lưu trữ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>PostgreSQL</strong> (<code>Relational &amp; Financial DB</code>)</td><td style="text-align:left;">Lưu trữ dữ liệu định danh, tổ chức đa tầng, hợp đồng gói dịch vụ, chiến dịch, tài chính, hóa đơn SePay, ví AI Credit và hàng đợi gửi email cần tính toàn vẹn giao dịch ACID (<code>@Transactional</code>).</td><td style="text-align:left;"><code>users</code>, <code>agencies</code>, <code>agency_members</code>, <code>agency_invitations</code>, <code>workspaces</code>, <code>workspace_members</code>, <code>workspace_templates</code>, <code>client_profiles</code>, <code>media_packages</code>, <code>workspace_media_packages</code>, <code>media_campaigns</code>, <code>content_requests</code>, <code>subscription_plans</code>, <code>user_subscriptions</code>, <code>invoices</code>, <code>agency_credit_wallets</code>, <code>workspace_credit_limits</code>, <code>credit_reservations</code>, <code>ai_credit_prices</code>, <code>mail_batches</code>, <code>mail_deliveries</code>, <code>mail_suppressions</code>, <code>newsletter_usage</code>, <code>share_links</code>.</td></tr><tr><td style="text-align:left;"><strong>MongoDB</strong> (<code>Content &amp; Workflow Document Store</code>)</td><td style="text-align:left;">Lưu trữ dữ liệu công việc đa định dạng (8 loại <code>TaskType</code>), trình soạn chia phần (<code>TaskSection</code>), lịch sử phiên bản, bài đăng mạng xã hội, khảo sát, thư viện tư liệu, mẫu email, danh bạ KOL và tin nhắn chat thời gian thực.</td><td style="text-align:left;"><code>tasks</code> (<code>TaskDocument</code> + embedded <code>Subtask</code>), <code>task_sections</code>, <code>task_section_versions</code>, <code>task_section_events</code>, <code>task_approvals</code>, <code>posts</code> (<code>PostDocument</code>), <code>surveys</code>, <code>survey_responses</code>, <code>materials</code>, <code>hashtag_collections</code>, <code>mail_templates</code>, <code>mail_recipient_groups</code>, <code>brand_knowledge_docs</code>, <code>collaborators</code>, <code>chat_channels</code>, <code>chat_messages</code>, <code>moderation_items</code>.</td></tr><tr><td style="text-align:left;"><strong>Neo4j</strong> (<code>AI Trend Knowledge Graph</code>)</td><td style="text-align:left;">Lưu trữ đồ thị tri thức xu hướng phục vụ khám phá xu hướng (<code>3.7.1</code>, <code>3.7.2</code>) và cung cấp ngữ cảnh đồ thị cho AI sinh nội dung (<code>3.7.6</code>).</td><td style="text-align:left;">Nút (<code>Nodes</code>): <code>TrendTopic</code>, <code>Keyword</code>, <code>Hashtag</code>, <code>Platform</code>, <code>Industry</code>, <code>ContentAngle</code>. Cạnh (<code>Relationships</code>): <code>RELATES_TO</code>, <code>TRENDING_ON</code>, <code>HAS_HASHTAG</code>, <code>SUGGESTS_ANGLE</code>.</td></tr><tr><td style="text-align:left;"><strong>Redis</strong> (<code>Cache, Session, Rate-Limit &amp; Pub/Sub</code>)</td><td style="text-align:left;">Lưu mã OTP xác thực, danh sách thu hồi/phiên JWT, khóa phân tán, bộ giới hạn tốc độ (<code>ChatRateLimiter</code>, <code>NewsletterTestRateLimiter</code>) và hàng đợi đệm.</td><td style="text-align:left;"><code>otp:*</code>, <code>auth:refresh:*</code>, <code>ratelimit:*</code>, <code>ws:presence:*</code>.</td></tr></tbody></table><hr><h2 id="_2-danh-muc-thuc-the-chi-tiet-theo-mien-nghiep-vu" tabindex="-1">2. Danh mục Thực thể Chi tiết theo Miền Nghiệp vụ <a class="header-anchor" href="#_2-danh-muc-thuc-the-chi-tiet-theo-mien-nghiep-vu" aria-label="Permalink to &quot;2. Danh mục Thực thể Chi tiết theo Miền Nghiệp vụ&quot;">​</a></h2><h3 id="_2-1-nhom-đinh-danh-to-chuc-khong-gian-lai-3-2-3-3-3-4" tabindex="-1">2.1. Nhóm Định danh, Tổ chức &amp; Không gian Lai (<code>3.2</code>, <code>3.3</code>, <code>3.4</code>) <a class="header-anchor" href="#_2-1-nhom-đinh-danh-to-chuc-khong-gian-lai-3-2-3-3-3-4" aria-label="Permalink to &quot;2.1. Nhóm Định danh, Tổ chức &amp; Không gian Lai (`3.2`, `3.3`, `3.4`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Thực thể (Bảng / Collection)</th><th style="text-align:center;">CSDL</th><th style="text-align:left;">Các Trường Cốt lõi (Key Attributes)</th><th style="text-align:left;">Quan hệ &amp; Quy tắc Nghiệp vụ (Business Invariants)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>User</code></strong> (<code>users</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id (UUID)</code>, <code>email (UNIQUE)</code>, <code>password_hash</code>, <code>display_name</code>, <code>avatar_url</code>, <code>system_role (USER | ADMIN)</code>, <code>two_factor_enabled</code>, <code>working_language (vi | en)</code>, <code>violation_status</code>, <code>status (ACTIVE | BANNED | DELETED)</code></td><td style="text-align:left;">Liên kết <code>1-N</code> với <code>Agency</code> (vai trò <code>Owner</code>), <code>1-N</code> với <code>AgencyMember</code> và <code>WorkspaceMember</code>.</td></tr><tr><td style="text-align:left;"><strong><code>Agency</code></strong> (<code>agencies</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id (UUID)</code>, <code>owner_id (FK users)</code>, <code>name</code>, <code>logo_icon</code>, <code>tagline</code>, <code>company_size</code>, <code>category</code>, <code>status (ACTIVE | DELETED)</code></td><td style="text-align:left;">Đại diện cho một Công ty truyền thông B2B hoặc một <strong><code>Personal Hub</code></strong> cá nhân (<code>logo_icon = &quot;personal-studio&quot;</code>). Mỗi <code>Agency</code> có đúng 1 <code>Owner</code> và 1 ví <code>AgencyCreditWallet</code>.</td></tr><tr><td style="text-align:left;"><strong><code>AgencyMember</code></strong> (<code>agency_members</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>agency_id</code>, <code>user_id</code>, <code>status (ACTIVE | REMOVED)</code>, <code>joined_at</code></td><td style="text-align:left;">Danh sách nhân sự thuộc <code>Agency</code> (<code>3.4.6</code>–<code>3.4.11</code>).</td></tr><tr><td style="text-align:left;"><strong><code>AgencyInvitation</code></strong> (<code>agency_invitations</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>agency_id</code>, <code>email</code>, <code>invited_by</code>, <code>target_workspace_id</code>, <code>target_workspace_role</code>, <code>language (vi | en)</code>, <code>personal_message</code>, <code>status (PENDING | ACCEPTED | DECLINED | EXPIRED)</code>, <code>expires_at</code></td><td style="text-align:left;">Lời mời tham gia <code>Agency</code> kèm xem trước bản mẫu email song ngữ (<code>3.4.8</code>–<code>3.4.10</code>).</td></tr><tr><td style="text-align:left;"><strong><code>Workspace</code></strong> (<code>workspaces</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id (UUID)</code>, <code>agency_id (FK agencies)</code>, <code>name</code>, <code>brand_name</code>, <code>timezone_config</code>, <code>status (ACTIVE | ARCHIVED | DELETED)</code>, <code>workspace_media_package_id</code>, <strong><code>settings (JSONB)</code></strong></td><td style="text-align:left;">Cột JSONB <code>settings</code> lưu <strong><code>&quot;workspaceMode&quot;: &quot;AGENCY&quot; | &quot;PERSONAL&quot;</code></strong> và <code>&quot;isPersonalDefault&quot;: true | false</code>. Các bản ghi cũ không có khóa này mặc định là <code>&quot;AGENCY&quot;</code>.</td></tr><tr><td style="text-align:left;"><strong><code>WorkspaceMember</code></strong> (<code>workspace_members</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>workspace_id</code>, <code>user_id</code>, <code>workspace_role (MANAGER | CREATOR | CLIENT)</code>, <code>client_profile_id</code>, <code>status (ACTIVE | REMOVED)</code></td><td style="text-align:left;">Ràng buộc <code>UNIQUE (workspace_id, user_id)</code>. Mỗi Workspace đang <code>ACTIVE</code> luôn có ít nhất 1 <code>MANAGER</code>. Trong Workspace <code>PERSONAL</code>, không có thành viên <code>CLIENT</code>.</td></tr><tr><td style="text-align:left;"><strong><code>ClientProfile</code></strong> (<code>client_profiles</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id (UUID)</code>, <code>workspace_id</code>, <code>display_name</code>, <code>logo_url</code>, <code>industry</code>, <code>website</code>, <code>contact_email</code>, <code>brand_guidelines</code></td><td style="text-align:left;">Hồ sơ thương hiệu của khách hàng (<code>3.3.3</code>–<code>3.3.4</code>). <code>display_name</code> được dùng làm tên người gửi Newsletter; <code>logo_url</code> được in vào file PDF/DOCX xuất ra.</td></tr><tr><td style="text-align:left;"><strong><code>WorkspaceTemplate</code></strong> (<code>workspace_templates</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>agency_id</code>, <code>name</code>, <code>description</code>, <code>template_config (JSONB)</code>, <code>created_by</code></td><td style="text-align:left;">Mẫu cấu hình Workspace tái sử dụng (<code>3.4.19</code>–<code>3.4.22</code>).</td></tr></tbody></table><h3 id="_2-2-nhom-goi-truyen-thong-chien-dich-yeu-cau-noi-dung-3-5" tabindex="-1">2.2. Nhóm Gói Truyền thông, Chiến dịch &amp; Yêu cầu Nội dung (<code>3.5</code>) <a class="header-anchor" href="#_2-2-nhom-goi-truyen-thong-chien-dich-yeu-cau-noi-dung-3-5" aria-label="Permalink to &quot;2.2. Nhóm Gói Truyền thông, Chiến dịch &amp; Yêu cầu Nội dung (`3.5`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Thực thể (Bảng / Collection)</th><th style="text-align:center;">CSDL</th><th style="text-align:left;">Các Trường Cốt lõi (Key Attributes)</th><th style="text-align:left;">Quan hệ &amp; Quy tắc Nghiệp vụ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>MediaPackage</code></strong> (<code>media_packages</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>agency_id</code>, <code>name</code>, <code>description</code>, <code>offerings (JSONB: serviceType, quantity, unit, price)</code>, <code>total_price</code>, <code>is_template</code></td><td style="text-align:left;">Danh mục gói dịch vụ mẫu của <code>Agency</code> (<code>3.5.1</code>, <code>3.5.2</code>). Hỗ trợ đủ 8 loại <code>PackageServiceType</code> (<code>CONTENT_POST</code>, <code>SHORT_VIDEO</code>, <code>SURVEY</code>, <code>EVENT_PLAN</code>, <code>PRESS_RECOMMENDATION</code>, <code>KOL_BOOKING</code>, <code>WORKSHOP_SUPPORT</code>, <code>EMAIL_NEWSLETTER</code>).</td></tr><tr><td style="text-align:left;"><strong><code>WorkspaceMediaPackage</code></strong> (<code>workspace_media_packages</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>workspace_id</code>, <code>source_package_id</code>, <code>custom_name</code>, <code>offerings (JSONB)</code>, <code>status (DRAFT | REQUESTED | APPROVED)</code></td><td style="text-align:left;">Gói dịch vụ áp dụng cho một Workspace (<code>3.5.3</code>, <code>3.5.4</code>). Ở chế độ <code>PERSONAL</code>, hệ thống tự cấp ngầm gói khung không giới hạn để người dùng lập Chiến dịch cá nhân ngay.</td></tr><tr><td style="text-align:left;"><strong><code>MediaCampaign</code></strong> (<code>media_campaigns</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>workspace_id</code>, <code>workspace_media_package_id</code>, <code>name</code>, <code>objective</code>, <code>start_date</code>, <code>end_date</code>, <code>work_items (JSONB)</code>, <code>status (DRAFT | ACTIVE | COMPLETED)</code></td><td style="text-align:left;">Chiến dịch truyền thông (<code>3.5.5</code>–<code>3.5.9</code>). Khi <code>deploy</code>, sinh ra các <code>TaskDocument</code> cha và bộ <code>Subtask</code> theo vai trò chuẩn.</td></tr><tr><td style="text-align:left;"><strong><code>ContentRequest</code></strong> (<code>content_requests</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>workspace_id</code>, <code>client_user_id</code>, <code>title</code>, <code>type</code>, <code>description</code>, <code>desired_due_date</code>, <code>status (PENDING | APPROVED | REJECTED | CANCELLED)</code>, <code>linked_task_id</code></td><td style="text-align:left;">Yêu cầu nội dung do <code>Client</code> gửi từ <code>Client Portal</code> (<code>3.5.10</code>–<code>3.5.13</code>).</td></tr></tbody></table><h3 id="_2-3-nhom-cong-viec-đa-đinh-dang-trinh-soan-chia-phan-cong-tac-3-6" tabindex="-1">2.3. Nhóm Công việc Đa định dạng, Trình soạn Chia phần &amp; Cộng tác (<code>3.6</code>) <a class="header-anchor" href="#_2-3-nhom-cong-viec-đa-đinh-dang-trinh-soan-chia-phan-cong-tac-3-6" aria-label="Permalink to &quot;2.3. Nhóm Công việc Đa định dạng, Trình soạn Chia phần &amp; Cộng tác (`3.6`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Thực thể (Bảng / Collection)</th><th style="text-align:center;">CSDL</th><th style="text-align:left;">Các Trường Cốt lõi (Key Attributes)</th><th style="text-align:left;">Quan hệ &amp; Quy tắc Nghiệp vụ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>TaskDocument</code></strong> (<code>tasks</code>)</td><td style="text-align:center;">Mongo</td><td style="text-align:left;"><code>id</code>, <code>workspaceId</code>, <code>campaignId</code>, <strong><code>type (8 TaskTypes)</code></strong>, <code>title</code>, <code>description</code>, <code>status (TODO | IN_PROGRESS | IN_REVIEW | FINISHED | CANCELLED)</code>, <code>priority</code>, <code>assigneeId</code>, <code>dueDate</code>, <strong><code>requiresClientApproval</code></strong>, <code>sourceType</code>, <code>workflowRevision</code>, <code>lastSubmission</code>, <strong><code>subtasks: List&lt;Subtask&gt;</code></strong></td><td style="text-align:left;">Hỗ trợ 8 loại <code>TaskType</code> chuẩn (<code>POST</code>, <code>SHORT_VIDEO</code>, <code>SURVEY</code>, <code>EVENT_PLAN</code>, <code>PRESS_RECOMMENDATION</code>, <code>KOL_BOOKING</code>, <code>WORKSHOP</code>, <code>EMAIL_NEWSLETTER</code>). Trong <code>Subtask</code> có trường <strong><code>subtaskRole</code></strong> gắn với <code>TaskCatalog</code>. Trong chế độ <code>PERSONAL</code>, <code>requiresClientApproval = false</code> và hỗ trợ <code>self-approve</code> 1 chạm.</td></tr><tr><td style="text-align:left;"><strong><code>TaskSectionDocument</code></strong> (<code>task_sections</code>)</td><td style="text-align:center;">Mongo</td><td style="text-align:left;"><code>id (taskId|sectionKey)</code>, <code>workspaceId</code>, <code>taskId</code>, <strong><code>sectionKey</code></strong>, <strong><code>visibility (OUTPUT | INTERNAL)</code></strong>, <strong><code>status (DRAFT | SUBMITTED | INTERNAL_APPROVED | CLIENT_APPROVED | RETURNED)</code></strong>, <code>revision</code>, <code>content (Map)</code>, <code>returnNote</code>, <code>clientPendingSince</code></td><td style="text-align:left;">Lưu trữ trạng thái, revision CAS và nội dung của từng phần trong trình soạn thảo chia phần. Phần <code>INTERNAL</code> bị lọc bỏ hoàn toàn khi <code>Client</code> truy vấn.</td></tr><tr><td style="text-align:left;"><strong><code>TaskSectionVersionDocument</code></strong> (<code>task_section_versions</code>)</td><td style="text-align:center;">Mongo</td><td style="text-align:left;"><code>id (taskId|sectionKey|versionNo)</code>, <code>taskId</code>, <code>sectionKey</code>, <code>versionNo</code>, <code>content (Snapshot)</code>, <code>submittedBy</code>, <code>submittedAt</code></td><td style="text-align:left;">Bản chụp lịch sử bất biến mỗi khi chủ phần bấm <code>Submit</code> (<code>3.6.34</code>); cho phép xem diff từng dòng và khôi phục (<code>Restore</code>).</td></tr><tr><td style="text-align:left;"><strong><code>TaskSectionEventDocument</code></strong> (<code>task_section_events</code>)</td><td style="text-align:center;">Mongo</td><td style="text-align:left;"><code>id</code>, <code>taskId</code>, <code>sectionKey</code>, <code>action (SUBMIT | APPROVE | RETURN | REOPEN | CLIENT_APPROVE | CLIENT_RETURN | SELF_APPROVE)</code>, <code>actorId</code>, <code>note</code>, <code>at</code></td><td style="text-align:left;">Nhật ký kiểm toán đầy đủ cho mọi thao tác duyệt/trả/mở lại phần.</td></tr><tr><td style="text-align:left;"><strong><code>PostDocument</code></strong> (<code>posts</code>)</td><td style="text-align:center;">Mongo</td><td style="text-align:left;"><code>id</code>, <code>workspaceId</code>, <code>taskId</code>, <code>contentText</code>, <code>hashtags</code>, <code>media (List&lt;PostMedia&gt;)</code>, <code>targetPlatforms (FB | IG | TIKTOK | THREADS)</code>, <code>scheduledAt</code>, <code>status (DRAFT | APPROVED | SCHEDULED | PUBLISHING | PUBLISHED | FAILED)</code></td><td style="text-align:left;">Lưu nội dung xuất bản của công việc <code>POST</code> và <code>SHORT_VIDEO</code> (<code>3.6.1</code>–<code>3.6.9</code>, <code>3.8.5</code>–<code>3.8.15</code>).</td></tr><tr><td style="text-align:left;"><strong><code>Material</code></strong> (<code>materials</code>)</td><td style="text-align:center;">Mongo</td><td style="text-align:left;"><code>id</code>, <code>workspaceId</code>, <code>folderId</code>, <code>name</code>, <code>mimeType</code>, <code>sizeBytes</code>, <code>storageUrl</code>, <code>watermarkedUrl</code>, <code>driveFileId</code>, <code>clientVisible</code>, <code>tags</code></td><td style="text-align:left;">Thư viện tư liệu số của Workspace, hỗ trợ đóng dấu <code>Watermark</code> (<code>3.6.18</code>), đồng bộ <code>Google Drive</code> (<code>3.6.15</code>–<code>3.6.17</code>) và chia sẻ thư mục cho <code>Client</code> / <code>Guest</code>.</td></tr><tr><td style="text-align:left;"><strong><code>MailBatch</code> &amp; <code>MailDelivery</code></strong> (<code>mail_batches</code>, <code>mail_deliveries</code>, <code>newsletter_usage</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>workspace_id</code>, <code>agency_id</code>, <strong><code>kind (SEND | TEST | NEWSLETTER)</code></strong>, <code>status</code>, <code>scheduled_at</code>, <code>total_count</code>, <code>sent_count</code>, <code>failed_count</code></td><td style="text-align:left;">Hạ tầng gửi email mẫu (<code>3.6.28</code>–<code>3.6.32</code>) và gửi bản tin <code>EMAIL_NEWSLETTER</code> thật với bộ đếm hạn mức tháng theo <code>Agency</code> (<code>newsletter_usage</code>: <code>1.000</code> / <code>10.000</code> / <code>50.000</code>).</td></tr><tr><td style="text-align:left;"><strong><code>ShareLink</code></strong> (<code>share_links</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>token (UNIQUE)</code>, <code>workspace_id</code>, <code>resource_type (MEDIA_PACKAGE | POST | DOCUMENT | FOLDER)</code>, <code>resource_id</code>, <code>expires_at</code>, <code>revoked_at</code></td><td style="text-align:left;">Đường dẫn chia sẻ công khai chỉ-đọc cho <code>Guest</code> (<code>/s/:token</code>).</td></tr></tbody></table><h3 id="_2-4-nhom-ai-mang-xa-hoi-tai-chinh-quan-tri-3-7-3-8-3-9-3-10" tabindex="-1">2.4. Nhóm AI, Mạng xã hội, Tài chính &amp; Quản trị (<code>3.7</code>, <code>3.8</code>, <code>3.9</code>, <code>3.10</code>) <a class="header-anchor" href="#_2-4-nhom-ai-mang-xa-hoi-tai-chinh-quan-tri-3-7-3-8-3-9-3-10" aria-label="Permalink to &quot;2.4. Nhóm AI, Mạng xã hội, Tài chính &amp; Quản trị (`3.7`, `3.8`, `3.9`, `3.10`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Thực thể (Bảng / Collection)</th><th style="text-align:center;">CSDL</th><th style="text-align:left;">Các Trường Cốt lõi (Key Attributes)</th><th style="text-align:left;">Quan hệ &amp; Quy tắc Nghiệp vụ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>BrandKnowledgeDoc</code></strong> (<code>brand_knowledge_docs</code>)</td><td style="text-align:center;">Mongo + Vector</td><td style="text-align:left;"><code>id</code>, <code>workspaceId</code>, <code>fileName</code>, <code>fileUrl</code>, <code>chunkCount</code>, <code>status (PROCESSING | INDEXED | FAILED)</code></td><td style="text-align:left;">Tài liệu tri thức thương hiệu phục vụ RAG khi sinh nội dung AI (<code>3.7.3</code>–<code>3.7.5</code>).</td></tr><tr><td style="text-align:left;"><strong><code>Collaborator</code></strong> (<code>collaborators</code>)</td><td style="text-align:center;">Mongo</td><td style="text-align:left;"><code>id</code>, <code>agencyId</code>, <code>name</code>, <code>platforms</code>, <code>niche</code>, <code>followerCount</code>, <code>engagementRate</code>, <code>rateCardVnd</code>, <code>contactInfo</code></td><td style="text-align:left;">Hồ sơ KOL / Influencer / Cộng tác viên trong danh bạ Agency (<code>3.7.15</code>–<code>3.7.19</code>).</td></tr><tr><td style="text-align:left;"><strong><code>SocialAccount</code></strong> (<code>social_accounts</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>id</code>, <code>workspace_id</code>, <strong><code>platform (FACEBOOK | INSTAGRAM | TIKTOK | THREADS)</code></strong>, <code>account_id</code>, <code>account_name</code>, <code>access_token_enc</code>, <code>status (CONNECTED | EXPIRED | DISCONNECTED)</code></td><td style="text-align:left;">Tài khoản mạng xã hội kết nối vào Workspace (<code>3.8.1</code>, <code>3.8.2</code>). Chỉ hỗ trợ đúng 4 nền tảng chuẩn.</td></tr><tr><td style="text-align:left;"><strong><code>AgencyCreditWallet</code> &amp; <code>WorkspaceCreditLimit</code></strong> (<code>agency_credit_wallets</code>, <code>workspace_credit_limits</code>)</td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>agency_id</code>, <code>plan_balance</code>, <code>purchased_balance</code>, <code>held_balance</code>; <code>workspace_id</code>, <strong><code>cap (BIGINT NULLABLE)</code></strong>, <code>used_in_period</code>, <code>held_in_period</code>, <code>revision</code></td><td style="text-align:left;">Kiến trúc Ví tổng cấp Agency + Trần ngân sách cấp Workspace (<code>3.9.4</code>–<code>3.9.6</code>). <code>cap = NULL</code> là không giới hạn riêng; <code>cap = 0</code> là chặn tác vụ tính phí.</td></tr><tr><td style="text-align:left;"><strong><code>SubscriptionPlan</code>, <code>UserSubscription</code> &amp; <code>Invoice</code></strong></td><td style="text-align:center;">Postgres</td><td style="text-align:left;"><code>plan_code (BASIC | PLUS | ENTERPRISE)</code>, <code>price_vnd</code>, <code>credit_grant</code>; <code>invoice_code</code>, <code>sepay_reference</code>, <code>amount_vnd</code>, <code>status (PENDING | PAID | EXPIRED | CANCELLED)</code></td><td style="text-align:left;">Quản lý gói cước, thanh toán VietQR qua SePay và đối soát doanh thu (<code>3.9.1</code>–<code>3.9.3</code>, <code>3.10.6</code>–<code>3.10.14</code>).</td></tr></tbody></table><hr><h2 id="_3-cac-thuc-the-đa-loai-bo-khoi-pham-vi-de-scoped-entities-—-agents-md" tabindex="-1">3. Các Thực thể Đã Loại bỏ Khỏi Phạm vi (De-scoped Entities — <code>AGENTS.md</code>) <a class="header-anchor" href="#_3-cac-thuc-the-đa-loai-bo-khoi-pham-vi-de-scoped-entities-—-agents-md" aria-label="Permalink to &quot;3. Các Thực thể Đã Loại bỏ Khỏi Phạm vi (De-scoped Entities — `AGENTS.md`)&quot;">​</a></h2><ul><li><strong><code>LivestreamSession</code> / <code>LivestreamScript</code></strong>: Đã loại bỏ hoàn toàn theo quy tắc không làm tính năng Livestream.</li><li><strong><code>CopyrightCheckResult</code></strong>: Đã loại bỏ; chỉ sử dụng <code>ComplianceCheck</code> (<code>3.6.33</code>) và <code>ModerationItem</code> (<code>3.10.4</code>).</li><li><strong><code>MemberCreditLimit</code> (Hạn mức AI Credit theo từng cá nhân)</strong>: Đã được thay thế hoàn toàn bởi <code>WorkspaceCreditLimit</code> (<code>CREDIT_PERSONAL_LIMIT_RETIRED</code>).</li></ul>',18)])])}const y=t(n,[["render",a]]);export{u as __pageData,y as default};
